"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";

import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { RefreshIcon } from "../parts/icons";
import { RollingText } from "../parts/rolling-text";
import { ContactPanel } from "./delivery-tracker/contact-panel";
import { FIRST_STAGE, ITEMS, STAGES } from "./delivery-tracker/data";
import { StopTrack } from "./delivery-tracker/stop-track";
import { PinIcon } from "./icons";
import { SupplyArt } from "./supply-art";

/**
 * A live tracker for a clinic's supplies order: where the parcel is, when it
 * arrives, the five stops with a moving marker, the updates so far, what is
 * in it and where it goes. A button plays the next courier update, so the
 * whole journey can be followed.
 */
export function DeliveryTracker({ className }: { className?: string }) {
  const titleId = useId();
  const reduceMotion = useReducedMotion();
  const [stage, setStage] = useState(FIRST_STAGE);
  const current = STAGES[stage] ?? STAGES[0]!;
  const done = stage === STAGES.length - 1;
  const updates = STAGES.slice(0, stage + 1).reverse();

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-4 border-b border-border px-5 py-4">
        <div aria-live="polite" aria-atomic="true" className="min-w-0">
          <h2 id={titleId} className="text-xl font-semibold tracking-tight">
            {current.headline}
          </h2>
          <p className="text-sm text-muted-foreground">{current.where}</p>
        </div>
        <div className="text-left @md:text-right">
          <p className="text-sm text-muted-foreground">{done ? "Arrived at" : "Arriving by"}</p>
          <RollingText text={current.arrival} className="text-2xl font-semibold tracking-tight" />
          <p className="text-xs text-muted-foreground">{current.window}</p>
        </div>
      </header>

      <div className="border-b border-border px-2 py-5">
        <StopTrack stops={STAGES.map((item) => item.stop)} current={stage} />
      </div>

      <div className="grid @2xl:grid-cols-[1fr_17rem]">
        <section aria-labelledby={`${titleId}-updates`} className="flex flex-col gap-3 p-5">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <h3 id={`${titleId}-updates`} className="text-sm font-medium">
              Updates
            </h3>
            <Button variant="outline" size="sm" onClick={() => setStage((value) => (value >= STAGES.length - 1 ? 0 : value + 1))}>
              <RefreshIcon aria-hidden="true" className="size-4" />
              {done ? "Replay from the order" : "Play the next update"}
            </Button>
          </div>
          <ol className="flex flex-col">
            <AnimatePresence initial={false}>
              {updates.map((item, index) => (
                <motion.li
                  key={item.stop}
                  initial={reduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
                  animate={reduceMotion ? { opacity: 1 } : { opacity: 1, height: "auto" }}
                  transition={{ duration: 0.24, ease: [0.165, 0.84, 0.44, 1] }}
                  className="overflow-hidden"
                >
                  <div className="relative flex gap-3 pb-4">
                    <span aria-hidden="true" className="relative flex w-3 shrink-0 justify-center">
                      <span className={index === 0 ? "mt-1.5 size-3 rounded-full bg-chart-2" : "mt-1.5 size-2.5 rounded-full bg-border"} />
                      {index < updates.length - 1 ? <span className="absolute top-5 -bottom-3 w-px bg-border" /> : null}
                    </span>
                    <span className="flex flex-col">
                      <span className={index === 0 ? "text-sm font-medium" : "text-sm"}>{item.update}</span>
                      <span className="text-xs text-muted-foreground">{item.time}</span>
                    </span>
                  </div>
                </motion.li>
              ))}
            </AnimatePresence>
          </ol>
          <p className="text-xs text-muted-foreground">Last checked {current.time.replace(/^\w+ /, "")}</p>
        </section>

        <aside aria-label="Order details" className="flex flex-col gap-4 border-t border-border p-5 @2xl:border-t-0 @2xl:border-l">
          <div className="flex flex-col gap-3">
            <h3 className="text-sm font-medium">From Lindengrove Medical Supply</h3>
            <ul className="flex flex-col gap-3">
              {ITEMS.map((item) => (
                <li key={item.name} className="flex items-center gap-3">
                  <span className="h-12 w-10 shrink-0 overflow-hidden rounded-md border border-border">
                    <SupplyArt kind={item.kind} tone={item.tone} />
                  </span>
                  <span className="flex min-w-0 flex-col">
                    <span className="truncate text-sm">{item.name}</span>
                    <span className="text-xs text-muted-foreground">{item.detail}</span>
                  </span>
                </li>
              ))}
            </ul>
          </div>
          <div className="flex gap-2 text-sm">
            <PinIcon aria-hidden="true" className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
            <address className="not-italic">
              <span className="block font-medium">Fernhill, Harbour Street clinic</span>
              <span className="block text-muted-foreground">4 Quayside, Whitby YO21 1DH</span>
            </address>
          </div>
          <ContactPanel />
        </aside>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

