import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";

import { MessageIcon, XIcon } from "../../parts/icons";
import { PhoneIcon } from "../icons";

const NOTES = ["Leave with the front desk", "Use the side door on Church Lane", "Call when outside"] as const;

/**
 * A contact button that grows into the contact panel in its own place: the
 * driver, a call and a message action, and a delivery note to pick. Escape
 * or Close shrinks it back and returns the focus to the button.
 */
export function ContactPanel() {
  const reduceMotion = useReducedMotion();
  const noteLabel = useId();
  const [open, setOpen] = useState(false);
  const [note, setNote] = useState<(typeof NOTES)[number]>(NOTES[0]);
  const [sent, setSent] = useState(false);
  const opener = useRef<HTMLButtonElement>(null);
  const closer = useRef<HTMLButtonElement>(null);
  const wasOpen = useRef(false);

  useEffect(() => {
    if (open) closer.current?.focus();
    else if (wasOpen.current) opener.current?.focus();
    wasOpen.current = open;
  }, [open]);

  return (
    <motion.div
      layout={!reduceMotion}
      transition={{ type: "spring", stiffness: 320, damping: 34 }}
      className={cn("overflow-hidden border border-border", open ? "rounded-2xl" : "rounded-lg")}
      onKeyDown={(event) => {
        if (event.key === "Escape" && open) setOpen(false);
      }}
    >
      {open ? (
        <motion.div
          layout={reduceMotion ? false : "position"}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.18, delay: reduceMotion ? 0 : 0.08 }}
          className="flex flex-col gap-3 p-4"
          role="region"
          aria-label="Contact the courier"
        >
          <div className="flex items-start justify-between gap-3">
            <div>
              <p className="text-sm font-medium">Dani Kowalczyk, Swiftway Couriers</p>
              <p className="text-xs text-muted-foreground">Van 7, Whitby depot</p>
            </div>
            <Button ref={closer} variant="ghost" size="icon" aria-label="Close contact options" onClick={() => setOpen(false)} className="size-8">
              <XIcon aria-hidden="true" className="size-4" />
            </Button>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <Button variant="outline" size="sm">
              <PhoneIcon aria-hidden="true" className="size-4" />
              Call
            </Button>
            <Button variant="outline" size="sm">
              <MessageIcon aria-hidden="true" className="size-4" />
              Message
            </Button>
          </div>
          <div className="flex flex-col gap-1.5">
            <p id={noteLabel} className="mb-1.5 text-xs text-muted-foreground">
              Note for the driver
            </p>
            <RadioGroup
              aria-labelledby={noteLabel}
              value={note}
              onValueChange={(value) => {
                const picked = NOTES.find((option) => option === value);
                if (!picked) return;
                setNote(picked);
                setSent(false);
              }}
            >
              {NOTES.map((option) => (
                <label key={option} className="flex cursor-pointer items-center gap-2 text-sm">
                  <RadioGroupItem value={option} />
                  {option}
                </label>
              ))}
            </RadioGroup>
          </div>
          <div className="flex items-center justify-between gap-2">
            <p role="status" className="text-xs text-muted-foreground">
              {sent ? "The driver has your note." : ""}
            </p>
            <Button size="sm" disabled={sent} onClick={() => setSent(true)}>
              {sent ? "Note sent" : "Send note"}
            </Button>
          </div>
        </motion.div>
      ) : (
        <motion.div layout={reduceMotion ? false : "position"}>
          <Button ref={opener} variant="ghost" aria-expanded={false} onClick={() => setOpen(true)} className="w-full">
            <PhoneIcon aria-hidden="true" className="size-4" />
            Contact the courier
          </Button>
        </motion.div>
      )}
    </motion.div>
  );
}

