}

/**
 * Draws one product in a 4:5 frame from plain shapes, tinted with the
 * product's colour. It is decorative: the product's name says what it is.
 */
export function SupplyArt({ kind, tone, view = "front", fit = "contain", className }: SupplyArtProps) {
  const back = view === "back";
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      viewBox="0 0 100 125"
      preserveAspectRatio={fit === "cover" ? "xMidYMid slice" : "xMidYMid meet"}
      className={cn("size-full", className)}>
      <rect width="100" height="125" fill={`color-mix(in oklch, ${tone} 14%, oklch(0.97 0.006 80))`} />
      {view === "scene" ? (
        <>
          <rect y="100" width="100" height="25" fill={`color-mix(in oklch, ${tone} 22%, oklch(0.86 0.01 80))`} />
          <rect x="8" y="14" width="26" height="34" rx="2" fill={PAINT.window} />
        </>
      ) : (
        <ellipse cx="50" cy="108" rx="30" ry="4" fill={PAINT.shadow} />
      )}
      <g transform={view === "detail" ? "translate(-50 -62) scale(2)" : view === "scene" ? "translate(20 12) scale(0.75)" : undefined}>
        {drawing(kind, tone, back)}
      </g>
    </svg>
  );
}

"use client";

import type { CSSProperties } from "react";
import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

import { CheckIcon } from "../../parts/icons";
import { TruckIcon } from "../icons";

/** Props for the five-stop track. */
export interface StopTrackProps {
  stops: string[];
  /** The latest stop reached, from 0. */
  current: number;
}

/**
 * The parcel's way as a line of stops. Reached stops fill in, and the van
 * marker glides to the latest one on a spring; with reduced motion it jumps.
 * The list reads as an ordered list, and the latest stop is marked current.
 */
export function StopTrack({ stops, current }: StopTrackProps) {
  const reduceMotion = useReducedMotion();
  const last = stops.length - 1;
  const at = `${(current / last) * 100}%`;
  const transition = reduceMotion ? { duration: 0 } : { type: "spring" as const, stiffness: 170, damping: 26 };

  return (
    <div className="px-3">
      <div aria-hidden="true" className="relative mx-[10%] h-10">
        <span className="absolute inset-x-0 top-1/2 h-1 -translate-y-1/2 rounded-full bg-border" />
        <motion.span
          className="absolute top-1/2 left-0 h-1 -translate-y-1/2 rounded-full bg-chart-2"
          initial={false}
          animate={{ width: at }}
          transition={transition}
        />
        {/* Each stop is a dot on the line itself; the van stands in for the latest one. */}
        {stops.map((stop, index) =>
          index === current ? null : (
            <span
              key={stop}
              className={cn(
                "absolute top-1/2 left-(--stop-at) grid size-4 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full",
                index < current ? "bg-chart-2 text-card" : "border-2 border-border bg-card",
              )}
              // SAFETY: a CSS custom property, which inline style accepts.
              style={{ "--stop-at": `${(index / last) * 100}%` } as CSSProperties}
            >
              {index < current ? <CheckIcon className="size-3" /> : null}
            </span>
          ),
        )}
        <motion.span
          className="absolute top-1/2 grid size-9 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full border-2 border-chart-2 bg-card text-chart-2 shadow-sm"
          initial={false}
          animate={{ left: at }}
          transition={transition}
        >
          <TruckIcon className="size-4" />
        </motion.span>
      </div>
      <ol className="mt-1 grid grid-cols-5 gap-1 text-center">
        {stops.map((stop, index) => (
          <li
            key={stop}
            aria-current={index === current ? "step" : undefined}
            className={cn("text-xs", index <= current ? "text-foreground" : "text-muted-foreground")}
          >
            <span className={cn(index === current && "font-medium")}>{stop}</span>
            <span className="sr-only">{index < current ? ", done" : index === current ? ", latest" : ", to come"}</span>
          </li>
        ))}
      </ol>
    </div>
  );
}
